// Parse booking parameters and prepare Calendar event payload
const queryStr = $input.all()[0].json.query || '{}';
let params = {};
try {
  params = JSON.parse(queryStr);
} catch(e) {
  // If not JSON, try to extract from natural language - but for now require JSON
  return [{ json: { error: true, response: 'Could not parse booking parameters. Need JSON: {"datetime_iso":"...","customer_name":"..."}' } }];
}

const datetime_iso = params.datetime_iso || params.datetime || '';
const customer_name = params.customer_name || params.name || '';
const customer_phone = params.customer_phone || params.phone || '';
const customer_email = params.customer_email || params.email || '';
const service = params.service || '';
const notes = params.notes || '';

const TIMEZONE = 'Asia/Makassar';
const SLOT_MINUTES = 60;
const LOCATION = 'ILOT Legal Office, Bali';

if (!datetime_iso || !customer_name) {
  return [{ json: { error: true, response: 'Missing required info. Need datetime_iso and customer_name.' } }];
}

const startTime = new Date(datetime_iso);
const endTime = new Date(startTime.getTime() + SLOT_MINUTES * 60 * 1000);

const summary = 'Consultation: ' + customer_name + (service ? ' — ' + service : '');
const description = [
  'Customer: ' + customer_name,
  customer_phone ? 'WhatsApp: +' + customer_phone : '',
  customer_email ? 'Email: ' + customer_email : '',
  service ? 'Service: ' + service : '',
  notes ? 'Notes: ' + notes : ''
].filter(Boolean).join('\n');

const eventBody = {
  summary: summary,
  description: description,
  location: LOCATION,
  start: { dateTime: startTime.toISOString(), timeZone: TIMEZONE },
  end: { dateTime: endTime.toISOString(), timeZone: TIMEZONE },
  attendees: customer_email ? [{ email: customer_email }] : [],
  reminders: { useDefault: false, overrides: [{ method: 'popup', minutes: 60 }, { method: 'popup', minutes: 15 }] }
};

// Format date for display
const OFFSET_MS = 8 * 60 * 60 * 1000;
const wita = new Date(startTime.getTime() + OFFSET_MS);
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const dayName = days[wita.getUTCDay()];
const dateStr = months[wita.getUTCMonth()] + ' ' + wita.getUTCDate() + ', ' + wita.getUTCFullYear();
const h = wita.getUTCHours();
const ampm = h >= 12 ? 'PM' : 'AM';
const h12 = h > 12 ? h - 12 : (h === 0 ? 12 : h);
const timeStr = String(h12) + ':' + String(wita.getUTCMinutes()).padStart(2,'0') + ' ' + ampm + ' WITA';
const dateTimeFormatted = dayName + ', ' + dateStr + ' at ' + timeStr;

return [{ json: { error: false, eventBody: eventBody, startTime: startTime.toISOString(), customer_name: customer_name, customer_email: customer_email, service: service, dateTimeFormatted: dateTimeFormatted } }];

// Format successful booking confirmation
const calResp = $input.all()[0].json;
const bookingData = $('Parse Booking').all()[0].json;
const startTime = new Date(bookingData.startTime);

const OFFSET_MS = 8 * 60 * 60 * 1000;
const wita = new Date(startTime.getTime() + OFFSET_MS);
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const dayName = days[wita.getUTCDay()];
const dateStr = months[wita.getUTCMonth()] + ' ' + wita.getUTCDate() + ', ' + wita.getUTCFullYear();
const h = wita.getUTCHours();
const ampm = h >= 12 ? 'PM' : 'AM';
const h12 = h > 12 ? h - 12 : (h === 0 ? 12 : h);
const timeStr = String(h12) + ':' + String(wita.getUTCMinutes()).padStart(2,'0') + ' ' + ampm + ' WITA';

const msg = `Meeting booked successfully!

Date: ${dayName}, ${dateStr}
Time: ${timeStr}
Location: ILOT Legal Office, Bali
Customer: ${bookingData.customer_name}${bookingData.service ? '\nService: ' + bookingData.service : ''}

A calendar invite has been created. Please confirm to the customer that their consultation is booked.`;

return [{ json: { response: msg, dateTimeFormatted: dayName + ', ' + dateStr + ' at ' + timeStr } }];
